    coop_frac = coop_count / total if total > 0 else 0.5  # default neutral

    if observation['action'] == 'cooperate':
        # Cooperating: if the agent has been cooperative recently, smaller boost; otherwise larger
        if coop_frac > 0.5:
            boost = 0.03
        elif coop_frac > 0.2:
            boost = 0.08
        else:
            boost = 0.12
        # Extra help for negative reputations
        if current_reputation < -0.3:
            boost += 0.05
        return min(1.0, current_reputation + boost)
    else:  # defect
        # Defecting: punish more if the agent has been defecting often
        if coop_frac < 0.3:
            penalty = 0.35
        elif coop_frac < 0.6:
            penalty = 0.25
        else:
            penalty = 0.15
        # Extra punishment for already low reputation
        if current_reputation < -0.5:
            penalty += 0.10
        return max(-1.0, current_reputation - penalty)

